import java.util.*;

class Solution {
    private static class Node {
        Node[] next = new Node[26];
        String word;                        // set at the end of a word
    }

    public List<String> huntWords(char[][] board, String[] words) {
        Node root = new Node();
        for (String w : words) {
            Node cur = root;
            for (char ch : w.toCharArray()) {
                if (cur.next[ch - 'a'] == null) cur.next[ch - 'a'] = new Node();
                cur = cur.next[ch - 'a'];
            }
            cur.word = w;
        }
        List<String> found = new ArrayList<>();
        for (int i = 0; i < board.length; i++)
            for (int j = 0; j < board[0].length; j++) dfs(board, i, j, root, found);
        return found;
    }

    private void dfs(char[][] b, int i, int j, Node node, List<String> found) {
        if (i < 0 || j < 0 || i >= b.length || j >= b[0].length) return;
        char ch = b[i][j];
        if (ch == '#' || node.next[ch - 'a'] == null) return;   // used cell or dead prefix
        node = node.next[ch - 'a'];
        if (node.word != null) { found.add(node.word); node.word = null; }
        b[i][j] = '#';                                          // mark visited
        dfs(b, i + 1, j, node, found);
        dfs(b, i - 1, j, node, found);
        dfs(b, i, j + 1, node, found);
        dfs(b, i, j - 1, node, found);
        b[i][j] = ch;                                           // restore
    }
}

