class Solution:
    def huntWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        trie = {}
        for w in words:
            node = trie
            for ch in w: node = node.setdefault(ch, {})
            node["$"] = w
        R, C = len(board), len(board[0]); found = []
        def dfs(i, j, node):
            ch = board[i][j]
            nxt = node.get(ch)
            if nxt is None: return
            if "$" in nxt: found.append(nxt.pop("$"))
            board[i][j] = "#"
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < R and 0 <= b < C and board[a][b] != "#": dfs(a, b, nxt)
            board[i][j] = ch
        for i in range(R):
            for j in range(C): dfs(i, j, trie)
        return found

