function huntWords(board, words) {
  const root = Object.create(null);
  for (const w of words) { let nd = root; for (const ch of w) nd = nd[ch] || (nd[ch] = Object.create(null)); nd.$ = w; }
  const R = board.length, C = board[0].length, found = [];
  function dfs(i, j, node) {
    const ch = board[i][j], nx = node[ch];
    if (!nx) return;
    if (nx.$ !== undefined) { found.push(nx.$); delete nx.$; }
    board[i][j] = "#";
    if (i + 1 < R) dfs(i + 1, j, nx);
    if (i > 0) dfs(i - 1, j, nx);
    if (j + 1 < C) dfs(i, j + 1, nx);
    if (j > 0) dfs(i, j - 1, nx);
    board[i][j] = ch;
  }
  for (let i = 0; i < R; i++) for (let j = 0; j < C; j++) dfs(i, j, root);
  return found;
}
